import os, glob, subprocess
hits=[]
for root in ['.', '/tmp', '/data', os.path.expanduser('~'), '/home', '/mnt', '/workspace']:
    if os.path.isdir(root):
        for dirpath, dirnames, filenames in os.walk(root):
            # avoid huge traversals
            depth = dirpath.count(os.sep) - root.count(os.sep)
            if depth > 4:
                dirnames[:] = []
                continue
            dirnames[:] = [d for d in dirnames if not d.startswith('.') and d not in ('site-packages','node_modules','proc','sys')]
            for f in filenames:
                if 'fastq' in f.lower() or f.lower().endswith(('.fq','.fq.gz')):
                    hits.append(os.path.join(dirpath,f))
    if len(hits)>50: break
print(os.getcwd())
print(len(hits))
for h in hits[:50]: print(h, os.path.getsize(h))

import re
def modules(path):
    txt=open(path).read()
    mods={}
    cur=None
    for line in txt.split('\n'):
        if line.startswith('>>END_MODULE'):
            cur=None; continue
        if line.startswith('>>'):
            name,status=line[2:].rsplit('\t',1)
            cur=name; mods[cur]={'status':status,'lines':[]}
            continue
        if cur: mods[cur]['lines'].append(line)
    return mods

M={s:modules(f'/tmp/qc/{s}_fastqc/fastqc_data.txt') for s in ['reads_R1','reads_R2']}
for s in M:
    print('#'*15, s)
    print('\n'.join(M[s]['Basic Statistics']['lines']))

for s in M:
    print('#'*20, s)
    print('--- Per sequence GC content [%s]' % M[s]['Per sequence GC content']['status'])
    for l in M[s]['Per sequence GC content']['lines']:
        if l and not l.startswith('#'):
            gc,c = l.split('\t')
            if float(c)>0: print('  GC%',gc,'count',c)
    print('--- Overrepresented [%s]' % M[s]['Overrepresented sequences']['status'])
    print('\n'.join(M[s]['Overrepresented sequences']['lines'][:12]))
    print('--- Dedup pct:', [l for l in M[s]['Sequence Duplication Levels']['lines'] if 'Total Deduplicated' in l])

